import type { MonsterDef, MonsterKind } from "../types/game.js";
import { session } from "../runtime/session.js";

export const D: Record<MonsterKind, MonsterDef> = {
  crawler: { kind: "crawler", name: "Crawler", hp: 10, attack: 4 },
  stalker: { kind: "stalker", name: "Stalker", hp: 16, attack: 7 }
};
export const monsters = session.monsters;
const emit = (text: string) => {
  if (session.worldRef) session.worldRef.output.push({ kind: "text", text });
};
const roll = (a: number, b: number) =>
  a + Math.floor(session.nextRandom() * (b - a + 1));
export function attack() {
  if (!session.vitals.alive) return;
  if (!monsters.length) {
    session.say("nothing to attack");
    emit("swing at air");
    return;
  }
  const t = monsters[0], d = D[t.kind];
  let r = roll(1, 20) + session.combat.attackBonus;
  if (session.combat.torchBuffTicks > 0) r += 2;
  if (r >= 12) {
    t.hp -= 6 + session.combat.attackBonus;
    session.say(`you strike the ${d.name} (roll ${r})`);
    if (t.hp <= 0) {
      monsters.shift();
      session.mirror.stone += 2;
      session.inventory.stone += 2;
      session.say(`the ${d.name} falls`);
    }
  } else session.say(`you miss the ${d.name} (roll ${r})`);
  emit(`attack roll ${r}`);
}
export function equip(x: string) {
  if (!session.vitals.alive) return;
  if (x === "torch" && session.inventory.torch > 0) {
    session.equipment.weapon = "torch";
    session.say("you ready the torch");
    emit("equipped torch");
  } else {
    session.equipment.weapon = "fists";
    session.say("you ready your fists");
    emit("equipped fists");
  }
}
export function eat() {
  if (!session.vitals.alive) return;
  const i = session.inventory;
  if (i.ration <= 0) {
    session.say("no rations left");
    emit("nothing to eat");
    return;
  }
  i.ration--;
  session.vitals.hp = Math.min(session.vitals.maxHp, session.vitals.hp + 15 + i.torch);
  session.say("you eat a ration");
  emit("ate");
}
export function spawn(k: MonsterKind) {
  const d = D[k];
  monsters.push({ kind: k, hp: d.hp, attack: d.attack });
  session.say(`a ${d.name} emerges from the dark`);
}
