import type { GameSnapshot, LogEntry, MonsterInstance } from "../types/game.js";
import { session } from "../runtime/session.js";

export function snapshot(): GameSnapshot {
  const v = session.vitals, c = session.combat;
  return {
    tickCount: session.tickCount, hp: v.hp, maxHp: v.maxHp, wood: session.mirror.wood,
    stone: session.mirror.stone, inventory: { ...session.inventory },
    equippedWeapon: session.equipment.weapon, attackBonus: c.attackBonus,
    torchBuffTicks: c.torchBuffTicks, alive: v.alive, log: session.log.entries.slice(-20),
    monsters: session.monsters.map(m => ({ ...m })), rngState: session.rngState
  };
}

export function restore(raw: string) {
  const d = JSON.parse(raw) as GameSnapshot;
  session.tickCount = d.tickCount as number;
  session.vitals = { hp: d.hp as number, maxHp: d.maxHp as number, alive: d.alive as boolean };
  session.mirror = { wood: d.wood as number, stone: d.stone as number };
  session.inventory = d.inventory as typeof session.inventory;
  session.equipment.weapon = d.equippedWeapon as string;
  session.combat.attackBonus = d.attackBonus as number;
  session.combat.torchBuffTicks = d.torchBuffTicks as number;
  session.log.entries = (d.log as LogEntry[]).map(e => ({ ...e }));
  session.monsters.length = 0;
  for (const m of d.monsters as MonsterInstance[]) session.monsters.push({ ...m });
  session.rngState = d.rngState as number;
  session.say("save restored");
}

export function saveIfDue() {
  if (session.tickCount % 10 !== 0 || !session.worldRef) return;
  if (session.worldRef.storage.get("ventralis:save") === undefined) return;
  session.saveCounter++;
  session.worldRef.storage.set("ventralis:save", JSON.stringify({
    ...snapshot(), savedAtTick: session.tickCount, saveCounter: session.saveCounter
  }));
}
