import type { LogEntry, MonsterInstance, ScheduledEvent, World } from "../types/game.js";
import { defaultCombat, defaultEquipment, defaultInventory, defaultLog, defaultMirror, defaultVitals, type CombatModifiers, type Equipment, type EventLog, type Inventory, type ResourceMirror, type Vitals } from "../components/player.js";
export class GameSession {
  tickCount = 0; vitals: Vitals = defaultVitals(); inventory: Inventory = defaultInventory(); mirror: ResourceMirror = defaultMirror();
  equipment: Equipment = defaultEquipment(); combat: CombatModifiers = defaultCombat(); log: EventLog = defaultLog();
  monsters: MonsterInstance[] = []; pendingEvents: ScheduledEvent[] = []; rngState = 1; saveCounter = 0; worldRef: World | null = null;
  reset(seed: number): void { this.tickCount = 0; this.vitals = defaultVitals(); this.inventory = defaultInventory(); this.mirror = defaultMirror(); this.equipment = defaultEquipment(); this.combat = defaultCombat(); this.log = defaultLog(); this.pendingEvents = []; this.saveCounter = 0; this.monsters.length = 0; this.rngState = seed >>> 0; }
  nextRandom(): number { this.rngState = (this.rngState * 1664525 + 1013904223) >>> 0; return this.rngState / 4294967296; }
  say(message: string): void { this.log.entries.push({ tick: this.tickCount, message }); }
}
export const session = new GameSession();
